'use strict';
const $=s=>document.querySelector(s), storageKey='hard-workers-arcade-v1';
let tasks=[],activeId=null,rolling=false,toastTimer;
try{const saved=JSON.parse(localStorage.getItem(storageKey)||'[]');if(Array.isArray(saved))tasks=saved.filter(t=>t&&typeof t.id==='string'&&typeof t.title==='string'&&['ready','scored','done'].includes(t.status)&&Number.isFinite(t.points)&&t.points>=0).map(t=>({...t,note:typeof t.note==='string'?t.note:''}));}catch{setTimeout(()=>toast('Your browser could not load saved tasks.'),100);}
const el=(tag,cls,text)=>{const e=document.createElement(tag);e.className=cls||'';if(text!==undefined)e.textContent=text;return e;};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function save(){try{localStorage.setItem(storageKey,JSON.stringify(tasks));}catch{$('#save-label').textContent='Not saved · browser storage unavailable';toast('Browser storage is unavailable. Keep this tab open to keep your tasks.');}}
function addTask(title,note=''){if(typeof title!=='string'||!title.trim()||title.trim().length>160||typeof note!=='string'||note.length>500)throw Error('Enter a task of 1–160 characters and notes of up to 500 characters.');const task={id:crypto.randomUUID(),title:title.trim(),note:note.trim(),status:'ready',points:0};tasks.push(task);save();render();return task;}
function completeTask(id){const task=tasks.find(t=>t.id===id);if(!task||task.status!=='scored')throw Error('Roll this task before completing it.');task.status='done';save();render();toast(`Nice work! +${task.points} points banked.`);celebrate();return{id:task.id,points:task.points,status:task.status};}
function render(){const ready=tasks.filter(t=>t.status==='ready'),done=tasks.filter(t=>t.status==='done');$('#total').textContent=String(done.reduce((s,t)=>s+t.points,0)).padStart(4,'0');$('#done-count').textContent=done.length;$('#task-count').textContent=`${tasks.length} task${tasks.length===1?'':'s'}`;$('#balls').textContent=ready.length;$('#roll').disabled=rolling||!ready.length;$('#roll').textContent=rolling?'Rolling…':'Roll a task ↗';$('.led').textContent=rolling?'● BALL IN PLAY':ready.length?'● READY TO PLAY':'○ LOAD A TASK';const rack=$('#tasks');rack.replaceChildren();if(!tasks.length){const empty=el('div','empty-rack');empty.append(el('span','','◎'));const copy=el('div');copy.append(el('h3','','A clear rack. A fresh start.'),el('p','','Add your first task to put a ball in play.'));empty.append(copy);rack.append(empty);}
tasks.forEach(t=>{const card=el('article',`task ${t.status==='done'?'done':''}`),top=el('div','task-top');top.append(el('span','task-status',t.status==='ready'?'○ Ready to roll':t.status==='done'?`✓ ${t.points} points banked`:`◎ ${t.points} points to claim`));const remove=el('button','delete','×');remove.setAttribute('aria-label',`Delete task: ${t.title}`);remove.disabled=rolling;remove.onclick=()=>{tasks=tasks.filter(x=>x.id!==t.id);if(activeId===t.id)activeId=null;save();render();};top.append(remove);card.append(top,el('h3','',t.title));if(t.note)card.append(el('p','',t.note));if(t.status==='scored'){const complete=el('button','complete','Complete & bank ↗');complete.onclick=()=>completeTask(t.id);card.append(complete);}rack.append(card);});
const active=tasks.find(t=>t.id===activeId&&t.status==='scored')||tasks.find(t=>t.status==='scored');const panel=$('#active-task');panel.replaceChildren();panel.hidden=!active;$('#roll-guide').hidden=!!active;$('#next-title').textContent=active?active.title:'Let the lane decide.';$('#next-description').textContent=active?'Your ball has landed. These points are yours when the task is done.':'A ball, a little momentum, and one less decision to make.';if(active){if(active.note)panel.append(el('p','',active.note));const score=el('div','reserved',`+${active.points}`);score.append(el('small','','POINTS WAITING TO BE BANKED'));const button=el('button','primary','Complete & bank ✓');button.onclick=()=>completeTask(active.id);panel.append(score,button);}draw();}
$('#add-task').onclick=()=>{$('#task-dialog').showModal();$('#task-title').focus();};$('#close-dialog').onclick=()=>$('#task-dialog').close();$('#task-form').onsubmit=e=>{e.preventDefault();try{addTask($('#task-title').value,$('#task-note').value);$('#task-form').reset();$('#task-dialog').close();toast('Task added. One more ball in your rack.');}catch(error){toast(error.message);}};$('#help').onclick=()=>$('#help-dialog').showModal();$('#close-help').onclick=()=>$('#help-dialog').close();document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
const canvas=$('#lane'),ctx=canvas.getContext('2d');
const holes=[{x:241,y:112,r:38,p:100},{x:559,y:112,r:38,p:100},{x:400,y:153,r:44,p:50},{x:400,y:246,r:49,p:40},{x:400,y:348,r:53,p:30},{x:400,y:456,r:57,p:20}];
function path(points,fill,stroke,width=1){ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke();}}
function circle(x,y,r,fill,stroke,width=1){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke();}}
function draw(ball){ctx.clearRect(0,0,800,780);const bed=ctx.createLinearGradient(0,0,0,740);bed.addColorStop(0,'#231c30');bed.addColorStop(.6,'#242236');bed.addColorStop(1,'#363047');path([[210,54],[590,54],[702,748],[98,748]],bed,'#675273',2);ctx.save();ctx.shadowBlur=15;ctx.shadowColor='#ee61b1';path([[193,54],[207,54],[101,748],[84,748]],'#d972b1','#ff9bd1',2);path([[593,54],[607,54],[716,748],[699,748]],'#d972b1','#ff9bd1',2);ctx.restore();path([[210,54],[590,54],[595,77],[205,77]],'#604565','#ba70a3',2);ctx.save();ctx.shadowBlur=9;ctx.shadowColor='#74dcf7';ctx.strokeStyle='#5fa1bd';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(400,330,176,238,0,0,2*Math.PI);ctx.stroke();ctx.restore();holes.forEach(h=>{ctx.save();ctx.shadowBlur=10;ctx.shadowColor=h.p===100?'#ff77bd':'#60c4df';circle(h.x,h.y,h.r,'#11121e',h.p===100?'#e886bf':'#74bfda',4);ctx.restore();circle(h.x,h.y+3,h.r-9,'#15131f','#373442',2);ctx.fillStyle=h.p===100?'#ffb7df':'#c1e6f1';ctx.font=`500 ${h.p===100?23:26}px "Space Grotesk",sans-serif`;ctx.textAlign='center';ctx.fillText(h.p,h.x,h.y+9);});ctx.strokeStyle='#8c789740';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(132,609);ctx.quadraticCurveTo(400,665,668,609);ctx.stroke();const x=400+Number($('#aim').value)*175;ctx.save();ctx.setLineDash([5,11]);ctx.strokeStyle='#c998c450';ctx.beginPath();ctx.moveTo(400,685);ctx.lineTo(x,550);ctx.stroke();ctx.restore();if(!ball)ball={x:400,y:693,r:25};const grad=ctx.createRadialGradient(ball.x-8,ball.y-10,2,ball.x,ball.y,ball.r);grad.addColorStop(0,'#fff3f8');grad.addColorStop(.4,'#e0c6df');grad.addColorStop(1,'#86658e');ctx.save();ctx.shadowColor='#0009';ctx.shadowBlur=18;ctx.shadowOffsetY=8;circle(ball.x,ball.y,ball.r,grad,'#edc9e4',1);ctx.restore();}
$('#aim').oninput=()=>{if(!rolling)draw();};$('#power').oninput=()=>{if(!rolling)draw();};
async function rollTask(){const ready=tasks.filter(t=>t.status==='ready');if(rolling||!ready.length)throw Error('Add a task before rolling.');rolling=true;$('#aim').disabled=$('#power').disabled=true;const chosen=ready[Math.floor(Math.random()*ready.length)];const end={x:400+Number($('#aim').value)*175,y:505-Number($('#power').value)*405};const hit=holes.find(h=>Math.hypot(end.x-h.x,end.y-h.y)<h.r-7);render();await new Promise(resolve=>{const start=performance.now(),duration=matchMedia('(prefers-reduced-motion: reduce)').matches?50:1100;function frame(now){const t=Math.min(1,(now-start)/duration),ease=1-(1-t)**2;draw({x:400+(end.x-400)*ease,y:693+(end.y-693)*ease,r:25-13*ease});if(t<1)requestAnimationFrame(frame);else resolve();}requestAnimationFrame(frame);});chosen.points=hit?hit.p:10;chosen.status='scored';activeId=chosen.id;rolling=false;$('#aim').disabled=$('#power').disabled=false;save();render();toast(`${hit?hit.p+' points!':'10 effort points!'} Your next task: ${chosen.title}`);return{id:chosen.id,title:chosen.title,points:chosen.points};}
$('#roll').onclick=()=>rollTask().catch(error=>toast(error.message));
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<42;i++){const bit=el('span','confetti');bit.style.left=Math.random()*100+'%';bit.style.background=i%2?'#ff77bd':'#74dcf7';bit.style.animationDelay=Math.random()*.4+'s';$('#confetti').append(bit);setTimeout(()=>bit.remove(),2400);}}
render();if(document.fonts)document.fonts.ready.then(()=>draw());
if(document.modelContext?.registerTool){const tools=[{name:'list_arcade_tasks',description:'Read tasks, roll status, and points in this device-local arcade.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({tasks:tasks.map(t=>({...t}))})},{name:'add_arcade_task',description:'Create a task and add one ball to the rack on this device.',inputSchema:{type:'object',properties:{title:{type:'string',minLength:1,maxLength:160},note:{type:'string',maxLength:500}},required:['title'],additionalProperties:false},execute:input=>addTask(input.title,input.note??'')},{name:'roll_arcade_task',description:'Roll using the visible aim and power, randomly reveal an unrolled task, and reserve points.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>rollTask()},{name:'complete_arcade_task',description:'Mark a rolled task complete and bank its points. Use only when the task has been finished.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},execute:input=>completeTask(input.id)}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}
